{
  "version": "v1",
  "hooks": [
    {
      "name": "Run the tests",
      "description": "Sean prepared this from the repository's own manifests: run the tests after a file is saved.",
      "trigger": "PostFileSave",
      "action": {
        "type": "command",
        "command": "npm run test"
      },
      "timeout": 120,
      "matcher": "\\.(py|ts|tsx)$"
    },
    {
      "name": "Run the linter",
      "description": "Sean prepared this from the repository's own manifests: run the linter after a file is saved.",
      "trigger": "PostFileSave",
      "action": {
        "type": "command",
        "command": "npm run lint"
      },
      "timeout": 120,
      "matcher": "\\.(py|ts|tsx)$"
    }
  ]
}
